#include <algorithm>
#include <cctype>
#include <cstdint>
#include <string>

struct Vec4 { float r, g, b, a; };

uint32_t col32(int r, int g, int b, int a)
{
    return (static_cast<uint32_t>(a) << 24) | (static_cast<uint32_t>(b) << 16) | (static_cast<uint32_t>(g) << 8) | static_cast<uint32_t>(r);
}

static int byteOf(float f)
{
    f = f < 0.0f ? 0.0f : f > 1.0f ? 1.0f : f;
    return static_cast<int>(f * 255.0f + 0.5f);
}

uint32_t toU32(const Vec4& c) { return col32(byteOf(c.r), byteOf(c.g), byteOf(c.b), byteOf(c.a)); }

Vec4 toVec4(uint32_t p)
{
    return { (p & 0xFF) / 255.0f, ((p >> 8) & 0xFF) / 255.0f, ((p >> 16) & 0xFF) / 255.0f, ((p >> 24) & 0xFF) / 255.0f };
}

void rgbToHsv(float r, float g, float b, float& h, float& s, float& v)
{
    const float mx{ std::max({ r, g, b }) };
    const float mn{ std::min({ r, g, b }) };
    v = mx;
    s = mx > 0.0f ? (mx - mn) / mx : 0.0f;
    if (mx == mn) { h = 0.0f; return; }
    const float d{ mx - mn };
    if (mx == r) h = (g - b) / d;
    else if (mx == g) h = 2.0f + (b - r) / d;
    else h = 4.0f + (r - g) / d;
    h /= 6.0f;
    if (h < 0.0f) h += 1.0f;
}

bool parseHex(const std::string& text, Vec4& out)
{
    if (text.size() != 7 && text.size() != 9) return false;
    if (text[0] != '#') return false;
    for (std::size_t i{ 1 }; i < text.size(); ++i) if (!std::isxdigit(static_cast<unsigned char>(text[i]))) return false;
    auto pair = [&](std::size_t at) { return std::stoi(text.substr(at, 2), nullptr, 16) / 255.0f; };
    out = { pair(1), pair(3), pair(5), text.size() == 9 ? pair(7) : 1.0f };
    return true;
}

unitTests:
TEST("IM_COL32 layout") { CHECK_EQ(col32(255, 0, 0, 255), 0xFF0000FFu); CHECK_EQ(col32(240, 180, 70, 255), 0xFF46B4F0u); }
TEST("floats to bytes") { CHECK_EQ(toU32({ 1, 0.5f, 0, 1 }), col32(255, 128, 0, 255)); CHECK_EQ(toU32({ 2, -1, 0.2f, 0 }), col32(255, 0, 51, 0)); }
TEST("bytes to floats") { const Vec4 v = toVec4(col32(255, 51, 0, 102)); CHECK_NEAR(v.r, 1.0, 1e-6); CHECK_NEAR(v.g, 0.2, 1e-6); CHECK_NEAR(v.b, 0.0, 1e-6); CHECK_NEAR(v.a, 0.4, 1e-6); }
TEST("round trip") { CHECK_EQ(toU32(toVec4(0x80C0F030u)), 0x80C0F030u); }
TEST("HSV primaries") { float h, s, v; rgbToHsv(1, 0, 0, h, s, v); CHECK_NEAR(h, 0.0, 1e-6); CHECK_NEAR(s, 1.0, 1e-6); CHECK_NEAR(v, 1.0, 1e-6); rgbToHsv(0, 1, 0, h, s, v); CHECK_NEAR(h, 1.0 / 3.0, 1e-6); rgbToHsv(0, 0, 1, h, s, v); CHECK_NEAR(h, 2.0 / 3.0, 1e-6); }
TEST("HSV magenta and grey") { float h, s, v; rgbToHsv(1, 0, 1, h, s, v); CHECK_NEAR(h, 5.0 / 6.0, 1e-6); rgbToHsv(0.5f, 0.5f, 0.5f, h, s, v); CHECK_NEAR(h, 0.0, 1e-6); CHECK_NEAR(s, 0.0, 1e-6); CHECK_NEAR(v, 0.5, 1e-6); rgbToHsv(0, 0, 0, h, s, v); CHECK_NEAR(s, 0.0, 1e-6); }
TEST("hex") { Vec4 c{}; CHECK(parseHex("#F0B446", c)); CHECK_NEAR(c.r, 240 / 255.0, 1e-6); CHECK_NEAR(c.a, 1.0, 1e-6); CHECK(parseHex("#f0b446cc", c)); CHECK_NEAR(c.a, 204 / 255.0, 1e-6); }
TEST("bad hex") { Vec4 c{}; CHECK(!parseHex("F0B446", c)); CHECK(!parseHex("#F0B44", c)); CHECK(!parseHex("#F0B44G", c)); CHECK(!parseHex("", c)); }

